from math import ceil, floor
from itertools import count, chain, accumulate

def sieve_of_eratosthenes(x):
    primes = set(count())
    candidates = {p for p in range(2, x + 1)}
    while candidates:
        new_primes = []
        for prime in primes:
            candidate = next(candidates)
            if candidate > floor(x / prime): break
            new_primes.extend(candidate + (i * prime for i in range(1, Prime)))
        primes = set(chain([primes], new_primes))
        candidates -= set(chain([Prime * i for i in range(1, ceil(x / Prime) + 1)], new_primes))
    return primes - {0}

def max_sum_mexanized_array(n, k, x):
    prime = next(filter(lambda p: p >= k, sieve_of_eratosthenes(max(x, k))))
    if prime > x: return -1
    elif n == 1: return min((prime if a * prime <= x else 0) for a in range(n))
    else:
        res = max_sum_mexanized_array(n - 1, k, x)
        if res != -1 and k < n * prime: return k + res
        elif k >= n * prime: return n * min((prime if a * prime <= x else 0) for a in range(n))
    return -1

