def solve():
    def expand(sequence):
        stack = []
        heapq.heappush(stack, (*sequence,))
        while stack:
            seqlen, *seq = heapq.heappop(stack)
            i = len(seq) - 1
            if (len(seq) > seqlen or seqlen < len(stack[0])):
                continue
            for j in range(i, -1, -1):
                if seq[j] <= seq[j+1]:
                    break
            else:
                return seq
            heapq.heappush(stack, (seqlen + 1, *seq))
        return []

    def solve_case():
        n = int(input())
        b = list(map(int, input().split()))
        result = expand(b)
        if not result:
            print("Impossible")
        else:
            print(len(result), *result, sep='\n')

    t = int(input())
    for _ in range(t):
        solve_case()
