        count = 0
        mask = -1
        curr = 0
        for num in bits:
            mask ^= (num << count)
            count += 1
            if num:
                curr |= ((mask & (1<<count)) != 0) << (count-1)
            else:
                curr &= ~((mask & (1<<count)) != 0) << (count-1)
