import sys
from collections import deque
from functools import lru_cache

def get_z Function(s):
    n = len(s)
    z = [0] * n
    left, right, LMP = 0, 0, -1
    for i in range(n):
        while (right + 1 < n and i + right + 1 < n and s[i+right + 1] == s[right + 1]) :
            right += 1
            z[i + right] = min(z[i], right)
        if i + right >= n:
            break
        while (left <= i and right + 1 < n and s[left + 1] == s[right + 1]) :
            left += 1
            z[i + right + 1] = min(z[i + right], left)
            if z[i + right] == left - i: break
    return z

def suffix_array(s):
    n = len(s)
    SA, rank = [i for i in range(n)], [0] * n
    for k in range(1, int(n ** 0.5 + 2)):
        CP, CND = deque(), [0] * n
        for i in range(n):
            rank[SA[i]] = i
            CP.append((-s[i], i))
        for _ in range(1, n):
            temp, CND_next = deque(), []
            for _ in range(n - 1+k*2):
                cp = CP.popleft()
                while len(CP) > cp[0]:
                    cnp = CP[-1]
                    if cnp[0] >= k:
                        break
                    CND[cnp[1]] += cp[0] > cnp[0]
                    CP.popleft()
                temp.append((CP, CND))
            for cp, cnd in temp:
                cp.append((cp[-1][0], cp[-1][1] + k, rank[cp[-1][1]]))
            for i in range(n):
                CND_next[i] = cnd[i - k] - cnd[i] if 0 < i - k else 0
            CP, CND = [x[0] for x in sorted(zip(*temp), key=lambda x:x[-1])], CND_next
            SA2 = [SA[i] for i in range(n) if cp[i].pop()[0] == 0]
            for i, j in enumerate(range(n-1, -1, -1)):
                if not cp[j][0]:
                    SA[CP[CP[i][1]][1]] = SA2[i]
        return SA

def prefix_array(s):
    n = len(s)
    P = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        while i < n and s[P[i + 1]] == s[i]:
            i += 1
        P[i] = P[i+1] + 1
    return P

@lru_cache(maxsize=2**30)
def kmp_match(s, p):
    m, n = len(s), len(p)
    if not n: return range(m)
    fails = [0]*(n+1)
    j = 0
    for i in range(m):
        while j and s[i] != p[j]:
            j = fails[j]
        if s[i] == p[j]:
            j += 1
        if j == n:
            return [i - n + 1]
        fails[i+1] = fails[j]
    return []

def solve():
    t = int(sys.stdin.readline())
    for _ in range(t):
        s_length = int(sys.stdin.readline())
        ss = sys.stdin.readline().strip()
        sa = suffix_array(ss + '$' + reversed(ss))[-s_length - 1::-1]
        sp = prefix_array(reversed(ss)[1:])[1:]
        answers = [('YES' if i in kmp_match(ss, ss[sa[i]:]) and i in kmp_match(reversed(ss), reversed(ss)[sp[i]:]) else 'NO') for i in range(s_length)]
        print('\n'.join(answers))
