import itertools

def solve():
    def find_permutation(nums, curr=(), diff=-1):
        if not nums:
            yield curr
            return

        for perm in find_permutation(nums[1:], (nums[0],) + curr):
            new_diff = abs(perm[-1] - perm[-2]) if curr else abs(nums[0] - nums[1])      # check the minimum diff with the first two elements or the last two consecutive elemnts in the current permutation
            if new_diff > diff:
                yield from find_permutation(nums[1:], perm)

    lines = []
    for i in range(1, 1001):
        lines.append(sorted([j <= i for j in range(1, i+1)], reverse=True))     # generates the lexicographically smallest permutation as a list of booleans
        perm = [i for _, val in enumerate(lines[-1]) if val]              # converts the list of boolean values to an actual permutation
        lines.append(' '.join(str(x) for x in perm))                         # print the permutation as a string
    return '\n'.join(lines[1:])                # exclude initial empty line generated by sorted() function
