from typing import List
import functools
from math import ceil

class LazySegmentTree:
    def __init__(self, n: int):
        assert n > 1
        self.size = n
        self.log = functools.reduce(lambda a, b: 1 if (a & b) == 0 else a + 1, (2, self.size - 1), 0)
        self.data = [0] * (2 * self.size)

    def update(self, idx: int, x: int, v: int, node: int, l: int, r: int):
        if l > r or idx < l or r < idx:
            return None
        if l == r:
            self.data[node] += x * v
            return self.data[node]
        m = (l + r) // 2
        self.update(idx, x, v, node * 2, l, m)
        self.update(idx, x, v, node * 2 + 1, m + 1, r)
        self.data[node] = self.data[node * 2] + self.data[node * 2 + 1]
        return self.data[node]

    def query(self, l: int, r: int):
        ans = 0
        for s in range(ceil(self.log), 0, -1):
            m = (self.size ** s)
            l_l = (l + m - 1) // m
            r_r = (r + m - 1) // m
            ans += self.data[m * l_l] if l_l <= self.size else 0
            ans -= self.data[m * r_r + m - 1] if r_r < self.size else 0
        return (r - l + 1) * ans

def solve():
    n, q = map(int, input().split())
    a = list(map(int, input().split()))
    st = LazySegmentTree(n)
    for _ in range(q):
        t, x = map(int, input().split())
        s = st.query(1, n)
        if t == 0:
            s += x * sum([i for i in a if i % 2 == 0])
            for i in range(n):
                if a[i] % 2 == 0:
                    st.update(i + 1, x, 1, 1, 1, n)
        elif t == 1:
            s += x * sum([i for i in a if i % 2 != 0])
            for i in range(n):
                if a[i] % 2 != 0:
                    st.update(i + 1, x, 1, 1, 1, n)
        print(s)

if __name__ == "__main__":
