from math import ceil
import sys
from functools import lru_cache

sys.setrecursionlimit(10 ** 5)
mod = int(1e9 + 7)

class BitMaskingTree():
    def __init__(self, n):
        self.n = n
        self.tree = [0] * (2 * n)

    @lru_cache(maxsize=None)
    def _parent(self, i):
        return (i - 1) // 2 if i > 0 else None

    def update(self, idx, val):
        i = self.n + idx
        while i > 0:
            self.tree[i] = (self.tree[i] + val) % mod
            i = self._parent(i)

    @lru_cache(maxsize=None)
    def sum_range(self, s, e):
        a, d, res = 0, 0, 0
        e += 1
        while s < e:
            if s & 1 == 1:
                a += self.tree[s]
                a %= mod
                s += 1
            if e & 1 == 0:
                d += self.tree[e - 1]
                d %= mod
                e -= 1
            s = (s + 1) // 2
            e = (e - 1) // 2
        if s != 0:
            d += self.tree[s - 1]
            d %= mod
        if e != s:
            a += self.tree[e]
            a %= mod
        res = (d + a) % mod
        return res

def solve():
    n, q = map(int, input().split())
    tree = BitMaskingTree(n << 1)
    arr = list(map(int, input().split()))
    for x in arr:
        tree.update(x, 1)
    ans = [tree.sum_range(1, n)]
    for _ in range(q):
        qtype, x = map(int, input().split())
        if qtype == 0:
            tree.update(1, (tree.sum_range(1, n) << 1) + x)
        elif qtype == 1:
            tree.update(n, (x - (tree.sum_range(1, n - 1))) << 1)
        ans.append(tree.sum_range(1, n))
    return ans

if __name__ == "__main__":
    print('\n'.join(map(str, solve())))
