import sys
from math import *

def max_beauty(m):
    dp = [[0] * m for _ in range(m)]

    def inner(i, j):
        nonlocal dp
        if i > j:
            return 0
        if dp[i][j] != 0:
            return dp[i][j]

        val = float('-inf') if i == j else max(dp[i+1][j], dp[i][j-1])
        for k in range(i,j):
