import sys
from itertools import product, cycle

def is_reached(board, i, j):
    moves = ((0, 1), (1, 0))
    for dx, dy in moves:
        if not (0 <= i+dx < board[0] and 0 <= j+dy < board[1]):
            continue
        reached = set()
        while True:
            x, y = i+dx*2, j+dy*2
            if board[x][y] == "G":
                reached.add((dx, dy))
            elif board[x][y] != "*" and (dx, dy) not in reached:
                break
            else:
                x, y = x + dx*2, y + dy*2
        if len(reached) > 1 and any((0, 1) == dx^dy for dx, dy in reached):
            return True
    return False

def chip_winner(board):
    board[0][0] = "*"
    players = cycle(["Burenka", "Tonya"])
    while True:
        winner = None
        for player in players:
            moves = ((i, j) for i, j in product(range(board[0]), range(board[1])) if board[i][j] == "G" and not is_reached(board, i, j))
            if len(moves) == 0:
                return player
            move = next(moves)
            board[move] = "*"
            winner = player
        board[move] = "G"
        if not is_reached(board, move):
            return winner

def main():
    for _ in range(int(sys.stdin.readline().strip())):
        n, m = list(map(int, sys.stdin.readline().split()))
        board = [["G" if (i == 0 or j == 0) else "B" for j in range(m+2)] for i in range(n+2)]
        for _ in range(1, n):
            board[0][2*i] = "B"
            board[-1 - i][2*i] = "Y" if (i % 2) else "*"
            for j in range(2, m+2, 2):
                board[-1 - i][j] = "*" if (i % 2) else "B"
        print(chip_winner(board))

if __name__ == "__main__":
