import collections
from typing import List

def bfs():
    queue = collections.deque([(0, 0, 1)])
    visited = {(0, 0): True}
    moves = {(x, y): [] for x in range(-100, 101) for y in range(-100, 101)}

    while queue:
        x, y, steps = queue.popleft()

        if (x, y) in visited:
            continue

        visited[(x, y)] = True

        moves[(x, y)] = steps
        if x > 0:
            queue.append((x - 1, y, steps + 1))
        if x < 100:
            queue.append((x + 1, y, steps + 1))
        if y > 0:
            queue.append((x, y - 1, steps + 1))
        if y < 100:
            queue.append((x, y + 1, steps + 1))

    def collect_boxes(boxes):
        steps = 0
        for b in boxes:
            x, y = b
            if (x, y) in visited:
                continue
            else:
                steps += moves[(x, y)]

        return steps + 1  # starting point

    def solution(n: int, boxes: List[List[int]]):
        if n == 0:
            return 0

        res = float('inf')
        for box in boxes:
            res = min(res, collect_boxes([box]))

        return res

