    def dfs(pos):
        if not pos or pos[-1] not in (0, 1):
            return float('inf')
        x, y = pos[-1] // m, pos[-1] % m
        if x == n and y == m:
            return pos[0]
        next_pos = {}
        for idx, p in enumerate(pos[:-1]):
            if (p + (1, 0)) in pos:
                next_pos[idx + 1] = (p, p + (1, 0))
            if (p + (0, 1)) in pos:
                next_pos[idx + 1] = (p, p + (0, 1))
        cost = float('inf')
        for i, new_path in enumerate(next_pos.items()):
            cost = min(cost, dfs(new_path[1]) + (i * m + y if next_path[1][-1] == (x+1,y) else i * m + x + 1))
        return cost
    print(dfs((0,(1,1))))

for _ in range(int(sys.stdin.readline())):
    solve()
