import heapq

def solve():
    def dijkstra(n, m):
        dist = [[float('inf')] * m for _ in range(n)]
        costs = [([1, 0], 1)]
        dist[0][0] = 1
        while costs:
            u, cost = heapq.heappop(costs)
            nu, nc = u
            if nu == n and nc == m:
                return cost
            for du, dc in ((nu + 1, nc), (nu, nc + 1)):
                if 0 <= du < n and 0 <= dc < m:
                    new_cost = dist[nu][nc] + ((nu - 1) * m + dc)
                    if new_cost < dist[du][dc]:
                        dist[du][dc] = new_cost
                        heapq.heappush(costs, ((du, dc), new_cost))
        return -1

    t = int(input())
    for _ in range(t):
        n, m = map(int, input().split())
        print(dijkstra(n, m))
